export function availableLayouts(lang){return lang==='ru'?['йцукен']:lang==='fr'?['azerty','qwerty','dvorak','colemak']:['qwerty','dvorak','colemak','qwertz'];}
export function mapPhysicalKeys(keys,layout){let q=LAYOUTS.qwerty.rows,l=LAYOUTS[layout].rows;return [...keys].map(k=>{for(let row=0;row<q.length;row++){let index=q[row].indexOf(k);if(index>=0)return l[row][index]||k}return k}).join('')}
export function findKey(char,layout){if(typeof char!=='string'||char.length!==1)return null;if(char==='\\'||char==='|')return{row:5,col:0,finger:7,shift:char==='|'};let l=LAYOUTS[layout];let numbers=numberRow(layout);for(let shifted of [false,true]){let col=(shifted?numbers.shift:numbers.base).indexOf(char);if(col>=0)return{row:-1,col,shift:shifted,finger:[0,0,1,2,3,3,4,4,5,6,7,7,7][col]}};if(char===' ')return{row:3,col:0,finger:8,shift:false};for(let row=0;row<l.rows.length;row++){let col=l.rows[row].indexOf(char),shift=false;if(col<0){col=l.shift[row].indexOf(char);shift=col>=0}if(col>=0){let zones=row===0?[0,1,2,3,3,4,4,5,6,7,7,7]:row===1?[0,1,2,3,3,4,4,5,6,7,7]:[0,1,2,3,3,4,4,5,6,7];return{row,col,shift,finger:zones[col]??7}}}return null}
